style.css:
/* Cutecore Candy v2 - bubbly, soft pink, all sites */
/* i really want this to be global */

/* swap these values to change the whole mood */
:root {
  --my-bg: #fff5f8;
  --my-text: #000000;
  --my-pink: #e87aa4;
  --my-pink-hover: #cf5a8a;
  --my-pink-soft: #ffd6e5;
  --my-font: "Chalkboard SE", "Comic Sans MS", "Marker Felt", ui-rounded, "Arial Rounded MT Bold", "Varela Round", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
}

/* blush pink background */
html, body {
  background-color: var(--my-bg) !important;
}

/* black text in a bubbly font, a little extra breathing room */
body, p, li, td, th, input, textarea, button, select {
  color: var(--my-text) !important;
  font-family: var(--my-font) !important;
  letter-spacing: 0.02em !important;
}
body, p, li {
  line-height: 1.7 !important;
}

/* soft pink headings with a candy shadow */
h1, h2, h3, h4, h5, h6 {
  color: var(--my-pink) !important;
  font-family: var(--my-font) !important;
  letter-spacing: 0.03em !important;
  text-shadow: 1px 1px 0 var(--my-pink-soft) !important;
}

/* little heart before the big headings (delete this block to remove) */
h1::before, h2::before, h3::before {
  content: "\2661  ";
}

/* pink links with a wavy underline */
a, a:visited {
  color: var(--my-pink) !important;
  text-decoration-style: wavy !important;
  text-underline-offset: 3px !important;
}
a:hover {
  color: var(--my-pink-hover) !important;
}

/* round, friendly images */
img {
  border-radius: 18px !important;
}

/* pillowy buttons and inputs */
button, input, textarea, select {
  border-radius: 16px !important;
  border: 2px solid var(--my-pink-soft) !important;
  background-color: #ffffff !important;
}

/* candy selection color */
::selection {
  background: var(--my-pink-soft) !important;
  color: var(--my-text) !important;
}

/* pink scrollbar */
html {
  scrollbar-color: var(--my-pink) var(--my-bg) !important;
}
